<?php
require __DIR__.'/app.php';require __DIR__.'/imi_lib.php';
try{$d=db();$u=isset($_SESSION['uid'])?q($d,'SELECT * FROM usuarios WHERE id=? AND activo=1',[$_SESSION['uid']])->fetch():null;}catch(PDOException $ex){go('index.php');}
if(!$u)go('index.php');
if(!imi_ready($d)){top('IMI · Registro mensual',$u);echo '<section class="card"><p>El administrador debe habilitar las tablas del módulo IMI.</p>';if($u['rol']==='admin')echo '<a class="button" href="actualizar_imi.php">Habilitar IMI</a>';echo '</section>';bottom();exit;}
$allowed=imi_establecimientos($d,$u);$ids=array_column($allowed,'id');
$eid=(int)($_POST['establecimiento_id']??$_GET['establecimiento_id']??($u['rol']==='establecimiento'?($u['establecimiento_id']??0):0));
if($eid&&!in_array($eid,$ids)){http_response_code(403);exit('El establecimiento no pertenece a su ámbito.');}
$month=(string)($_POST['mes']??$_GET['mes']??(new DateTimeImmutable('now',new DateTimeZone('America/Lima')))->format('Y-m'));
if(!preg_match('/^(20\d{2})-(0[1-9]|1[0-2])$/',$month)){http_response_code(422);exit('Periodo no válido. Use un mes entre 2000 y 2099.');}
$period=$month.'-01';
$microInput=$_POST['microred']??$_GET['microred']??'';$stateInput=$_POST['estado']??$_GET['estado']??'';
if(!is_scalar($microInput)||!preg_match('/^\d{0,9}$/',(string)$microInput)||!is_string($stateInput)){http_response_code(422);exit('Filtros no válidos.');}
$filterMicro=(int)$microInput;$filterState=$stateInput;$stateLabels=['pendiente'=>'Pendiente','borrador'=>'Borrador','enviado'=>'Enviado'];
if($filterState!==''&&!isset($stateLabels[$filterState])){http_response_code(422);exit('Estado de IMI no válido.');}
$filterMicros=[];foreach($allowed as $est)$filterMicros[$est['microred_id']]=$est['microred'];asort($filterMicros,SORT_NATURAL);
if($filterMicro&&!isset($filterMicros[$filterMicro])){http_response_code(403);exit('La microred no pertenece a su ámbito.');}
$states=array_column(q($d,'SELECT establecimiento_id,estado FROM imi_reportes WHERE periodo=?',[$period])->fetchAll(),'estado','establecimiento_id');
$filtered=array_values(array_filter($allowed,fn($est)=>(!$filterMicro||(int)$est['microred_id']===$filterMicro)&&($filterState===''||($states[$est['id']]??'pendiente')===$filterState)));
// Filters narrow the authorized scope; they never grant access to another establishment.
if($_SERVER['REQUEST_METHOD']!=='POST'&&$eid&&!in_array($eid,array_column($filtered,'id')))$eid=0;
$filterQuery=http_build_query(['microred'=>$filterMicro,'estado'=>$filterState]);
$window=q($d,'SELECT * FROM imi_periodos WHERE periodo=?',[$period])->fetch()?:null;$periodOpen=imi_periodo_abierto($window);$error='';$submitted=[];$ctx=$eid?imi_context($d,$eid,$period):null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();if(!in_array($u['rol'],['admin','establecimiento'],true)){http_response_code(403);exit('Su acceso a IMI es solo de consulta.');}
 try{
 if(!$eid)throw new RuntimeException('Seleccione el establecimiento.');
 $d->beginTransaction();$window=q($d,'SELECT * FROM imi_periodos WHERE periodo=? FOR UPDATE',[$period])->fetch()?:null;if(!imi_periodo_abierto($window)){http_response_code(403);throw new RuntimeException('El periodo está cerrado o fuera del plazo de ingreso. Solo puede consultar los IMI enviados.');}q($d,'SELECT id FROM establecimientos WHERE id=? FOR UPDATE',[$eid]);$ctx=imi_context($d,$eid,$period);$action=(string)($_POST['action']??'');
 if($action==='apertura'){
 if($u['rol']!=='admin'){http_response_code(403);throw new RuntimeException('Solo el administrador puede registrar saldos de apertura.');}
 if($ctx['latest'])throw new RuntimeException('La apertura se registra antes del primer informe y ya no puede modificarse después.');
 foreach($ctx['products'] as $p){$saldo=imi_num($_POST['saldo'][$p['id']]??null);q($d,'INSERT INTO imi_apertura(establecimiento_id,producto_id,saldo) VALUES(?,?,?) ON DUPLICATE KEY UPDATE saldo=VALUES(saldo)',[$eid,$p['id'],$saldo]);}
 }elseif($action==='reabrir'){
 if($u['rol']!=='admin'){http_response_code(403);throw new RuntimeException('Solo el administrador puede reabrir un informe.');}
 if(!$ctx['header']||$ctx['latest']['id']!==$ctx['header']['id'])throw new RuntimeException('Solo puede reabrirse el informe más reciente.');
 if((int)($_POST['version']??0)!==(int)$ctx['header']['version'])throw new RuntimeException('El informe cambió en otra sesión. Recargue la página.');
 q($d,'UPDATE imi_reportes SET estado=\'borrador\',version=version+1,actualizado_por=? WHERE id=?',[$u['id'],$ctx['header']['id']]);
 }elseif(in_array($action,['guardar','enviar'],true)){
 if($ctx['latest'] && $period<$ctx['latest']['periodo'])throw new RuntimeException('Los periodos anteriores son de consulta. Edite únicamente el informe más reciente.');
 if($ctx['header']&&$ctx['header']['estado']==='enviado')throw new RuntimeException('El informe está enviado. El administrador debe reabrirlo antes de modificarlo.');
 if($ctx['latest']&&$period>$ctx['latest']['periodo'] && $period!==(new DateTimeImmutable($ctx['latest']['periodo']))->modify('+1 month')->format('Y-m-d'))throw new RuntimeException('Registre los meses consecutivamente, sin saltarse periodos.');
 if($ctx['previous']&&$ctx['previous']['estado']!=='enviado')throw new RuntimeException('Envíe el informe del mes anterior antes de iniciar el siguiente.');
 if((int)($_POST['version']??0)!==(int)($ctx['header']['version']??0))throw new RuntimeException('El informe cambió en otra sesión. Recargue antes de guardar.');
 $submitted=$_POST['datos']??[];if(!is_array($submitted))throw new RuntimeException('Formulario incompleto.');
 foreach($ctx['products'] as $p)foreach(['stock_segun','recibido','consumo','ajuste'] as $key)imi_num($submitted[$p['id']][$key]??null);
 $rows=imi_rows($ctx,$submitted);foreach($rows as $row)if($row['calc']['final']<0)throw new RuntimeException('Saldo negativo en '.$row['producto']['codigo'].': consumo más ajustes supera el total disponible.');
 $state=$action==='enviar'?'enviado':'borrador';
 if($ctx['header']){$rid=$ctx['header']['id'];q($d,'UPDATE imi_reportes SET estado=?,version=version+1,actualizado_por=? WHERE id=?',[$state,$u['id'],$rid]);q($d,'DELETE FROM imi_detalles WHERE reporte_id=?',[$rid]);}
 else{q($d,'INSERT INTO imi_reportes(establecimiento_id,periodo,estado,actualizado_por) VALUES(?,?,?,?)',[$eid,$period,$state,$u['id']]);$rid=(int)$d->lastInsertId();}
 foreach($rows as $row){$r=$row['raw'];$c=$row['calc'];q($d,'INSERT INTO imi_detalles(reporte_id,producto_id,stock_segun,recibido,consumo,ajuste,stock_inicial,stock_final) VALUES(?,?,?,?,?,?,?,?)',[$rid,$row['producto']['id'],$r['stock_segun'],$r['recibido'],$r['consumo'],$r['ajuste'],$c['inicial'],$c['final']]);}
 }else throw new RuntimeException('Acción no válida.');
 if(!imi_periodo_abierto($window)){http_response_code(403);throw new RuntimeException('El plazo de ingreso ha vencido. No se guardaron cambios.');}$d->commit();$_SESSION['flash']='IMI: cambios guardados correctamente.';go('imi.php?establecimiento_id='.$eid.'&mes='.$month.'&'.$filterQuery);
 }catch(Throwable $ex){if($d->inTransaction())$d->rollBack();if($ex instanceof RuntimeException && !($ex instanceof PDOException))$error=$ex->getMessage();else{error_log($ex->getMessage());$error='No se guardó el informe. Revise los datos y vuelva a intentarlo.';}$ctx=$eid?imi_context($d,$eid,$period):null;}
}
$window=q($d,'SELECT * FROM imi_periodos WHERE periodo=?',[$period])->fetch()?:null;$periodOpen=imi_periodo_abierto($window);
$hiddenDraft=$ctx&&!$periodOpen&&$u['rol']!=='admin'&&(!$ctx['header']||$ctx['header']['estado']!=='enviado');
if($hiddenDraft){if(isset($_GET['exportar'])){http_response_code(403);exit('Periodo cerrado: solo se exportan informes enviados.');}$ctx=null;}
$editable=$periodOpen&&$ctx&&in_array($u['rol'],['admin','establecimiento'],true)&&(!$ctx['header']||$ctx['header']['estado']==='borrador')&&(!$ctx['latest']||$period>=$ctx['latest']['periodo']);
$rows=[];if($ctx){try{$rows=imi_rows($ctx,$submitted);}catch(RuntimeException $ex){$rows=imi_rows($ctx);}}
if(isset($_GET['exportar']) && $ctx){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="IMI_'.$eid.'_'.$month.'.csv"');echo "\xEF\xBB\xBF";$f=fopen('php://output','w');fputcsv($f,['Codigo','Medicamento o insumo','Tipo','Unidad','Stock inicial','Stock segun medicamentos','Recibido','Total','Consumo','Ajustes','Stock final','CPM','Meses existencia','Pedido sugerido saldo final','Pedido sugerido stock segun','Estado'],';', '"','');foreach($rows as $r){$p=$r['producto'];$v=$r['raw'];$c=$r['calc'];$texts=array_map(fn($s)=>preg_match('/^[=+@\-\t\r]/',(string)$s)?"'".$s:$s,[$p['codigo'],$p['nombre'],$p['tipo'],$p['unidad']]);fputcsv($f,array_merge($texts,[$c['inicial'],$v['stock_segun'],$v['recibido'],$c['total'],$v['consumo'],$v['ajuste'],$c['final'],round($c['cpm'],2),$c['meses']===null?'Sin base':round($c['meses'],2),$c['solicitar']??'Sin base',$c['segun']??'Sin base',$c['estado']]),';','"','');}fclose($f);exit;}
top('IMI · Informe mensual de movimientos',$u);
if($error)echo '<p class="alert">'.e($error).'</p>';if(isset($_SESSION['flash'])){echo '<p class="success">'.e($_SESSION['flash']).'</p>';unset($_SESSION['flash']);}
?>
<section class="card"><?php if($hiddenDraft):?><p class="alert">No hay un IMI enviado disponible para este establecimiento y periodo. Los borradores se conservan y podrán retomarse si el administrador abre el ingreso.</p><?php endif;?><p>Filtra los establecimientos por microred, estado y periodo. Selecciona un establecimiento para abrir su IMI. Las cuatro columnas turquesa se ingresan manualmente; las columnas azules se calculan automáticamente.</p><form method="get" class="filters"><label>Microred<select name="microred"><option value="">Todas las de mi ámbito</option><?php foreach($filterMicros as $id=>$name):?><option value="<?=e($id)?>" <?=$filterMicro==$id?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></label><label>Estado<select name="estado"><option value="">Todos los estados</option><?php foreach($stateLabels as $key=>$label):?><option value="<?=$key?>" <?=$filterState===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Establecimiento<select name="establecimiento_id"><option value="">Seleccionar para abrir un IMI</option><?php foreach($filtered as $e):?><option value="<?=$e['id']?>" <?=$eid==$e['id']?'selected':''?>><?=e($e['codigo'].' · '.$e['nombre'])?></option><?php endforeach;?></select></label><label>Periodo<input type="month" name="mes" value="<?=e($month)?>" min="2000-01" max="2099-12" required></label><button>Filtrar</button><a href="imi.php?mes=<?=e($month)?>">Limpiar filtros</a></form><p><?=count($filtered)?> establecimientos encontrados para el periodo <?=e($month)?>.</p></section>
<details class="card"><summary>Reglas de cálculo de esta prueba</summary><p>Stock inicial = saldo final del mes anterior; en el primer informe, saldo de apertura registrado por el administrador (por defecto cero). Total disponible = inicial + recibido. Stock final = total − consumo − ajustes. No se guardan saldos negativos.</p><p>CPM = promedio del consumo del mes actual y de los meses registrados dentro de los dos meses anteriores. Un mes sin registro no se interpreta como consumo cero. Se incluyen consumos cero cuando el mes sí está registrado. Pedido sugerido = máximo entre cero y el redondeo hacia arriba de (CPM × 3 − stock final). La segunda sugerencia usa el stock según medicamentos en lugar del saldo final.</p><p>“Stock según medicamentos” se conserva como saldo declarado para comparación; no reemplaza el saldo calculado. Si CPM = 0 se muestra “Sin base de consumo” para cobertura y pedidos. Alertas propuestas: menos de 1 mes = cobertura baja; más de 6 = sobrestock. Estos umbrales y las reglas deben validarse antes del uso operativo.</p><p>Los informes se registran en orden. Después de abrir el mes siguiente, el anterior queda de consulta para proteger los saldos. Los enviados requieren reapertura por el administrador; solo puede reabrirse el último periodo.</p></details>
<?php if($ctx):$estName='';foreach($allowed as $e)if($e['id']==$eid)$estName=$e['nombre']; ?>
<section class="card"><h2><?=e($estName)?> · <?=e($month)?></h2><p>Estado: <strong><?=e($ctx['header']['estado']??'pendiente')?></strong><?php if($ctx['header']):?> · Última modificación: <?=e($ctx['header']['actualizado_en'])?><?php endif;?></p><a class="button" href="imi.php?establecimiento_id=<?=$eid?>&amp;mes=<?=e($month)?>&amp;<?=e($filterQuery)?>&amp;exportar=1">Exportar CSV para Excel</a> <button type="button" onclick="window.print()">Imprimir</button><?php if(!$editable):?><p class="muted">Vista de consulta. Solo el administrador y el encargado asignado pueden ingresar datos de un periodo abierto.</p><?php endif;?></section>
<?php if($periodOpen&&$u['rol']==='admin'&&!$ctx['latest']):?><details class="card"><summary>Administrador: registrar saldo de apertura antes del primer IMI</summary><p>Ingrese el saldo inicial real de cada producto. Si no registra apertura, el sistema parte de cero. Esta opción se bloquea al guardar el primer informe.</p><form method="post"><?=token()?><input type="hidden" name="microred" value="<?=$filterMicro?>"><input type="hidden" name="estado" value="<?=e($filterState)?>"><input type="hidden" name="action" value="apertura"><input type="hidden" name="establecimiento_id" value="<?=$eid?>"><input type="hidden" name="mes" value="<?=e($month)?>"><div class="grid"><?php foreach($ctx['products'] as $p):?><label><?=e($p['codigo'].' · '.$p['nombre'])?><input type="number" name="saldo[<?=$p['id']?>]" min="0" max="999999999" step="1" value="<?=e($ctx['opening'][$p['id']]??0)?>" required></label><?php endforeach;?></div><button>Guardar saldos de apertura</button></form></details><?php endif;?>
<form method="post" id="imi-form"><?=token()?><input type="hidden" name="microred" value="<?=$filterMicro?>"><input type="hidden" name="estado" value="<?=e($filterState)?>"><input type="hidden" name="establecimiento_id" value="<?=$eid?>"><input type="hidden" name="mes" value="<?=e($month)?>"><input type="hidden" name="version" value="<?=e($ctx['header']['version']??0)?>"><div class="card table imi-wrap"><table class="imi-table"><thead><tr><?php foreach(['N°','Código','Medicamento o insumo','Tipo','Unidad','Stock inicial','Stock según medicamentos','Recibido en el periodo','Total disponible','Entregado a usuarias (consumo)','Ajuste vencidos / pérdidas / deterioro','Stock final','CPM','Meses de existencia','Cantidad sugerida a solicitar','Sugerida según medicamentos','Alerta'] as $i=>$h):?><th class="<?=in_array($i,[6,7,9,10],true)?'manual':'auto'?>"><?=e($h)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $i=>$row):$p=$row['producto'];$r=$row['raw'];$c=$row['calc'];?><tr data-initial="<?=$c['inicial']?>" data-history="<?=e(json_encode($row['history']))?>"><td><?=$i+1?></td><td class="code"><?=e($p['codigo'])?></td><td><?=e($p['nombre'])?></td><td><?=e($p['tipo'])?></td><td><?=e($p['unidad'])?></td><td><?=$c['inicial']?></td><?php foreach(['stock_segun','recibido'] as $k):?><td class="manual"><input aria-label="<?=e($k.' '.$p['codigo'])?>" type="number" min="0" max="999999999" step="1" data-key="<?=$k?>" name="datos[<?=$p['id']?>][<?=$k?>]" value="<?=$r[$k]?>" required <?=$editable?'':'disabled'?>></td><?php endforeach;?><td data-result="total"><?=$c['total']?></td><?php foreach(['consumo','ajuste'] as $k):?><td class="manual"><input aria-label="<?=e($k.' '.$p['codigo'])?>" type="number" min="0" max="999999999" step="1" data-key="<?=$k?>" name="datos[<?=$p['id']?>][<?=$k?>]" value="<?=$r[$k]?>" required <?=$editable?'':'disabled'?>></td><?php endforeach;?><td data-result="final"><?=$c['final']?></td><td data-result="cpm"><?=imi_format($c['cpm'])?></td><td data-result="meses"><?=imi_format($c['meses'])?></td><td data-result="solicitar"><?=imi_format($c['solicitar'])?></td><td data-result="segun"><?=imi_format($c['segun'])?></td><td data-result="estado"><?=e($c['estado'])?></td></tr><?php endforeach;?></tbody></table></div><?php if($editable):?><div class="card"><p>Guarda un borrador para continuar después, o envía el informe para dejarlo de consulta. Las cantidades deben ser enteras y no negativas.</p><button name="action" value="guardar">Guardar borrador</button> <button name="action" value="enviar">Enviar IMI</button></div><?php endif;?></form>
<?php if($periodOpen&&$u['rol']==='admin'&&$ctx['header']&&$ctx['header']['estado']==='enviado'&&$ctx['latest']['id']===$ctx['header']['id']):?><form method="post" class="card"><?=token()?><input type="hidden" name="microred" value="<?=$filterMicro?>"><input type="hidden" name="estado" value="<?=e($filterState)?>"><input type="hidden" name="establecimiento_id" value="<?=$eid?>"><input type="hidden" name="mes" value="<?=e($month)?>"><input type="hidden" name="version" value="<?=$ctx['header']['version']?>"><button name="action" value="reabrir">Reabrir último informe</button></form><?php endif;?>
<?php endif;?>
<section class="card table"><h2 class="imi-heading">Seguimiento del periodo · <?=e($month)?></h2><table><thead><tr><th>Establecimiento</th><th>Microred</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($filtered as $e):?><tr><td><?=e($e['nombre'])?></td><td><?=e($e['microred'])?></td><td><?=e($stateLabels[$states[$e['id']]??'pendiente'])?></td><td><?php if($periodOpen || $u['rol']==='admin' || ($states[$e['id']]??'')==='enviado'):?><a href="imi.php?establecimiento_id=<?=$e['id']?>&amp;mes=<?=e($month)?>&amp;<?=e($filterQuery)?>"><?=$periodOpen?'Abrir':'Consultar'?></a><?php else:?>Sin IMI enviado<?php endif;?></td></tr><?php endforeach;?><?php if(!$filtered):?><tr><td colspan="4">No se encontraron establecimientos con los filtros seleccionados.</td></tr><?php endif;?></tbody></table></section>
<script src="imi.js"></script><?php bottom();
